from jinja2 import Template, Environment, select_autoescape

# VULNERABLE — renders user input as template source
def render_greeting(name: str) -> str:
    return Template(f"Hello {name}!").render()  # SSTI if name contains {{}}

# SECURE — pass user input as a template variable, not template source
env = Environment(autoescape=select_autoescape())

def render_greeting(name: str) -> str:
    tmpl = env.from_string("Hello {{ name }}!")   # fixed template
    return tmpl.render(name=name)                  # name is data, not code

