import os

BASE_DIR = "/var/app/files"

# VULNERABLE — joins user path without canonicalization
def download_file(filename: str) -> bytes:
    path = os.path.join(BASE_DIR, filename)
    with open(path, 'rb') as f:  # ../../etc/passwd escapes BASE_DIR
        return f.read()

# SECURE — canonicalize and verify confinement
def download_file(filename: str) -> bytes:
    # realpath resolves symlinks and ../ before the check
    resolved = os.path.realpath(os.path.join(BASE_DIR, filename))
    if not resolved.startswith(BASE_DIR + os.sep):
        raise PermissionError("Path traversal detected")
    with open(resolved, 'rb') as f:
        return f.read()
